<?php
require_once __DIR__ . '/includes/functions.php';$user=require_role(['customer']);$orderId=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$stmt->execute([$orderId,$user['id']]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('Order not found.');}$stmt=db()->prepare('SELECT item_name,quantity,price_at_order,line_total FROM order_items WHERE order_id=?');$stmt->execute([$orderId]);$lines=$stmt->fetchAll();$pageTitle='Track your order';require __DIR__ . '/includes/header.php';?>
<section class="page-shell tracking-page" data-order-id="<?= (int)$order['id'] ?>"><div class="page-heading"><span class="eyebrow">ON ITS WAY TO YOUR TABLE</span><h1>Order <em>tracking.</em></h1><p>We’ll refresh this page every 15 seconds so you can stay in the loop.</p></div><div class="tracking-layout"><div class="content-card tracking-card"><div class="tracking-top"><div><span class="eyebrow">ORDER <?= e($order['order_number']) ?></span><h2 id="order-status-heading"><?= e($order['status']) ?></h2></div><span class="status-pill status-<?= strtolower($order['status']) ?>" id="order-status-pill"><?= e($order['status']) ?></span></div><div class="status-steps" id="status-steps"><?php foreach(['New','Preparing','Ready','Delivered'] as $step): ?><div class="status-step <?= array_search($order['status'],['New','Preparing','Ready','Delivered'],true)>=array_search($step,['New','Preparing','Ready','Delivered'],true)?'done':'' ?>"><span class="step-dot"><?= $step==='New'?'✓':($step==='Preparing'?'♨':($step==='Ready'?'✳':'⌂')) ?></span><b><?= e($step) ?></b></div><?php endforeach; ?></div><p class="tracking-updated">Last updated <span id="updated-time">just now</span> · automatically refreshes every 15 seconds</p></div><aside class="content-card order-summary"><span class="eyebrow">IN THE BAG</span><?php foreach($lines as $line): ?><div class="summary-line"><span><?= (int)$line['quantity'] ?> × <?= e($line['item_name']) ?></span><b><?= money($line['line_total']) ?></b></div><?php endforeach; ?><hr><div class="summary-line"><span>Subtotal</span><b><?= money($order['subtotal']) ?></b></div><div class="summary-line"><span>Delivery</span><b><?= money($order['delivery_fee']) ?></b></div><div class="summary-total"><span>Total</span><b><?= money($order['total']) ?></b></div><p class="muted">Delivering to<br><?= nl2br(e($order['delivery_address'])) ?></p></aside></div><a class="inline-link" href="orders.php">← Back to your orders</a></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('[data-order-id]');if(!root)return;const steps=['New','Preparing','Ready','Delivered'];async function refresh(){try{const r=await fetch('api/order-status.php?id='+root.dataset.orderId,{cache:'no-store'});if(!r.ok)return;const d=await r.json();document.querySelector('#order-status-heading').textContent=d.status;const pill=document.querySelector('#order-status-pill');pill.textContent=d.status;pill.className='status-pill status-'+d.status.toLowerCase();const current=steps.indexOf(d.status);document.querySelectorAll('.status-step').forEach((node,i)=>node.classList.toggle('done',i<=current));document.querySelector('#updated-time').textContent='just now';}catch(e){}}setInterval(refresh,15000);});</script>
<?php require __DIR__ . '/includes/footer.php'; ?>
